using System;
using System.Linq;
using System.Collections.Generic;
using System.Reflection;
using UnityEngine;
namespace AboutMe.Editor
{
    public static class PartyVirtualTests
    {
        static readonly FieldInfo Cache=typeof(CampusGeometry).GetField("solids",BindingFlags.NonPublic|BindingFlags.Static);
        public static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
        public static EffectState Auxiliary(Match m,string id,Vector3 position,Vector3? direction=null)
        {var d=PartyMechanicRegistry.Find(id);var e=new EffectState{id=Guid.NewGuid().ToString("N"),kind="PartyMechanic",owner="p2",sourceInstance=m.Players["p2"].equipped,mechanicId=id,position=position,velocity=direction??Vector3.forward,stage="field",createdAt=m.Time,deadline=m.Time+8,radius=d.radius,health=2};if(d.family=="machinery")e.machine=new MachineState();m.Effects.Add(e);return e;}
        public static EffectState Deploy(Match m,string id)
        {
            if(id=="weather-vane")Auxiliary(m,"turntable-wheel",new Vector3(0,.15f,3.7f));
            if(id=="frost-lock"){m.Players["p0"].bodyProtectedUntil=m.Time+5;var wet=Auxiliary(m,"wet-trail",new Vector3(0,.15f,0));wet.path=new[]{new Vector3(0,.15f,0),new Vector3(0,.15f,1)};}
            return PartyFieldTests.Deploy(m);
        }
        public static EffectState PortalPair(Match m)
        {var first=PartyFieldTests.Deploy(m);PartyFieldTests.Tick(m,.5f);PartyControlTests.Place(m,m.Players["p0"],new Vector3(3,1,0));m.Players["p0"].yaw=90;PartyFieldTests.Input(m,"p0","use_item");PartyFieldTests.Tick(m,.34f);Check(first.stage=="portal_in"&&m.Effects.Count(x=>x.mechanicId=="shot-portal")==2,"pair not connected "+first.stage+" events="+string.Join("/",m.Events.Select(x=>x.text)));return first;}
        public static void Run()
        {
            var old=Cache.GetValue(null);var failures=new List<string>();int passed=0;
            void Test(string name,Action run){Cache.SetValue(null,PartyControlTests.Flat);try{run();passed++;Debug.Log("PARTY_VIRTUAL_PASS "+name);}catch(Exception e){failures.Add(name+": "+e.Message);Debug.LogError("PARTY_VIRTUAL_FAIL "+name+": "+e);}}
            try
            {
                Test("ten virtual rules bind distinct actual prefabs",()=>{var all=PartyMechanicRegistry.All.Where(x=>x.family=="virtual").ToArray();Check(all.Length==10&&all.Select(x=>x.visualId).Distinct().Count()==10,"registry");foreach(var d in all)Check(Resources.Load<GameObject>("PersonaProps/"+d.visualId)!=null,"prefab "+d.visualId);});
                Test("portal rotates four ordinary shot types preserves energy ownership damage",()=>{foreach(var kind in new[]{"Projectile","Disc","ThrownDisc","Ricochet"})using(var m=PartyFieldTests.Make("shot-portal")){var e=PortalPair(m);var shot=PartyGuardTests.Shot(m,e.position+Vector3.up*.85f+e.velocity*.3f,-e.velocity*10,kind);PartyFieldTests.Tick(m,.08f);Check(shot.position.x>7&&shot.velocity.x>9.9f&&Mathf.Abs(new Vector2(shot.velocity.x,shot.velocity.z).magnitude-10)<.01f&&shot.owner=="p1"&&shot.damage==10&&m.CombatEvents.Count(x=>x.kind=="party_shot_portal")==1,"portal wrong "+kind+" pos="+shot.position+" velocity="+shot.velocity);}});
                Test("portal never teleports real Persona or people and each pair fires once",()=>{using(var m=PartyFieldTests.Make("shot-portal")){var e=PortalPair(m);var life=PartyGuardTests.Throw(m,e.position+Vector3.up*.85f+Vector3.forward*.3f,Vector3.back*10);var shot=PartyGuardTests.Shot(m,e.position+Vector3.up*.85f+Vector3.forward*.3f,Vector3.back*10);PartyControlTests.Place(m,m.Players["p1"],e.position+Vector3.up*.85f+Vector3.right*.5f);PartyFieldTests.Tick(m,.08f);Check(Mathf.Abs(life.position.x)<.01f&&life.ownerId=="p1"&&m.Players["p1"].position.x<1,"portal moved life/person");shot.position=e.position+Vector3.up*.85f+Vector3.forward*.1f;shot.velocity=Vector3.back*10;PartyFieldTests.Tick(m,.04f);Check(m.CombatEvents.Count(x=>x.kind=="party_shot_portal")==1,"portal loop");}});
                Test("portal reserves two device units and can finish at full cap",()=>{using(var m=PartyFieldTests.Make("shot-portal")){for(int i=0;i<6;i++)Auxiliary(m,"fan-volume",new Vector3(-20,.15f,i));PortalPair(m);Check(m.Effects.Count==8,"reserved capacity not finishable");}using(var m=PartyFieldTests.Make("shot-portal")){for(int i=0;i<7;i++)Auxiliary(m,"fan-volume",new Vector3(-20,.15f,i));PartyFieldTests.Input(m,"p0","use_item");PartyFieldTests.Tick(m,.34f);Check(m.Effects.Count==7&&m.View("p0").players.First(x=>x.id=="p0").mechanicCooldown<1,"unfinishable first portal placed");}});
                Test("portal rejects blocked exit without looping",()=>{using(var m=PartyFieldTests.Make("shot-portal")){var first=PortalPair(m);var exit=m.Effects.First(x=>x.stage=="portal_out");Cache.SetValue(null,PartyControlTests.Flat.Concat(new[]{new CampusSolid{name="exit wall",center=exit.position+Vector3.up*.85f+exit.velocity*.4f,size=new Vector3(.5f,2,2)}}).ToArray());var shot=PartyGuardTests.Shot(m,first.position+Vector3.up*.85f+Vector3.forward*.1f,Vector3.back*10);PartyFieldTests.Tick(m,.04f);Check(!m.CombatEvents.Any(x=>x.kind=="party_shot_portal")&&shot.position.x<1,"blocked teleport");}});
                Test("pixel parity flips bright grounded jump dark and airborne safe",()=>{using(var m=PartyFieldTests.Make("pixel-stamp")){var e=PartyFieldTests.Deploy(m);var b=m.Players["p1"];PartyControlTests.Place(m,b,e.position+Vector3.up*.85f+Vector3.right);PartyFieldTests.Tick(m,.04f);Check(!b.airborne,"dark launched");PartyControlTests.Place(m,b,e.position+Vector3.up*.85f);PartyFieldTests.Tick(m,.08f);Check(b.airborne&&b.motorHeight>1.1f&&m.CombatEvents.Count(x=>x.kind=="party_pixel_hop")==1,"bright failed");m.Time=e.createdAt+1.01f;PartyControlTests.Place(m,b,e.position+Vector3.up*.85f);PartyFieldTests.Tick(m,.02f);Check(!b.airborne,"flipped dark launched");PartyControlTests.Place(m,b,e.position+Vector3.up*.85f+Vector3.right);PartyFieldTests.Tick(m,.02f);Check(!b.airborne,"touch cooldown bypassed");}});
                Test("vector turn preserves planar vertical speeds and acts once",()=>{using(var m=PartyFieldTests.Make("vector-arrow")){var e=PartyFieldTests.Deploy(m);var shot=PartyGuardTests.Shot(m,e.position+Vector3.up*.85f+Vector3.right*1.5f,new Vector3(-10,1,0));PartyFieldTests.Tick(m,.04f);Check(shot.velocity.z>9.9f&&shot.velocity.y==1&&shot.owner=="p1","vector wrong");shot.velocity=Vector3.left*10;PartyFieldTests.Tick(m,.04f);Check(shot.velocity.x<-9&&m.CombatEvents.Count(x=>x.kind=="party_vector_turn")==1,"field turned twice");}});
                Test("echo records bounded path permits movement blocks E and Q cancels",()=>{using(var m=PartyFieldTests.Make("quantum-echo")){var e=PartyFieldTests.Deploy(m);var life=PartyFieldTests.Ground(m,new Vector3(.3f,.35f,0));PartyFieldTests.Input(m,"p0","interact");Check(life.state==ItemState.Ground,"record stole E");PartyFieldTests.Tick(m,.6f,"p0",1,0);Check(e.path.Length<=7&&e.path.Length>=3&&m.Players["p0"].position.x>1,"record locked or unbounded");PartyFieldTests.Input(m,"p0","cancel");Check(!m.Effects.Contains(e),"Q retained echo");}});
                Test("echo playback moves public box only and leaves people/lives",()=>{using(var m=PartyFieldTests.Make("quantum-echo")){var e=PartyFieldTests.Deploy(m);PartyFieldTests.Tick(m,.8f,"p0",1,0);var box=new PublicProp{id="echo-box",visual="box",position=new Vector3(1,.6f,0)};m.Props.Add(box);var life=PartyFieldTests.Ground(m,new Vector3(1,.35f,.3f));PartyControlTests.Place(m,m.Players["p1"],new Vector3(1,1,-.6f));var b=m.Players["p1"].position;PartyFieldTests.Tick(m,.85f);Check(m.CombatEvents.Any(x=>x.kind=="party_echo_push")&&box.position.x>1.1f&&life.position.x==1&&m.Players["p1"].position==b,"echo public filter failed");}});
                Test("lattice blocks loose box but admits held box life player and shot",()=>{using(var m=PartyFieldTests.Make("light-lattice")){var e=PartyFieldTests.Deploy(m);var box=new PublicProp{id="box",visual="box",position=e.position+Vector3.up*.45f+Vector3.forward*.2f,velocity=Vector3.back*8};m.Props.Add(box);var life=PartyGuardTests.Throw(m,e.position+Vector3.up*.6f+Vector3.right*.4f+Vector3.forward*.2f,Vector3.back*8);var shot=PartyGuardTests.Shot(m,e.position+Vector3.up*.85f+Vector3.left*.5f+Vector3.forward*.2f,Vector3.back*8);PartyControlTests.Place(m,m.Players["p1"],e.position+Vector3.up*.85f+Vector3.right*1);PartyFieldTests.Tick(m,.1f,"p1",0,-1);Check(box.position.z>=e.position.z&&box.velocity==Vector3.zero&&life.position.z<e.position.z&&shot.position.z<e.position.z&&m.Players["p1"].position.z<e.position.z-.2f,"lattice wrong classes box="+box.position+" life="+life.position);}});
                Test("side gravity pushes public only cap six and stops force when removed",()=>{using(var m=PartyFieldTests.Make("virtual-gravity")){var e=PartyFieldTests.Deploy(m);var box=new PublicProp{id="box",visual="box",position=e.position+Vector3.up*.45f};m.Props.Add(box);var held=new PublicProp{id="held",visual="trash",position=e.position+Vector3.up*.45f,holder="p1"};m.Props.Add(held);var life=PartyFieldTests.Ground(m,e.position+Vector3.up*.2f+Vector3.left*.4f);PartyFieldTests.Tick(m,.4f);Check(box.position.z>e.position.z+.2f&&box.velocity.magnitude<=6&&held.velocity==Vector3.zero&&Mathf.Abs(life.position.z-e.position.z)<.01f,"gravity classes/cap");e.deadline=m.Time;PartyFieldTests.Tick(m,.04f);Check(!m.Effects.Contains(e),"gravity stale");}});
                Test("shadow supports actors only and warns before removal",()=>{using(var m=PartyFieldTests.Make("solid-shadow")){var e=PartyFieldTests.Deploy(m);var b=m.Players["p1"];PartyControlTests.Place(m,b,e.position+Vector3.up*1.35f);Check(Mathf.Abs(m.SurfaceFloor(b.position)-.5f)<.01f&&m.SurfaceFloor(e.position+Vector3.up*.45f,.6f)==0&&m.SurfaceFloor(e.position+Vector3.up*.2f,.35f)==0,"shadow wrong surface class");PartyFieldTests.Tick(m,.12f);Check(b.motorHeight>1.45f,"shadow support failed "+b.motorHeight);m.Time=e.deadline-.7f;PartyFieldTests.Tick(m,.02f);Check(e.stage=="shadow_fading","no expiry warning");PartyFieldTests.Tick(m,.8f);Check(!m.Effects.Contains(e),"shadow expiry leak");}});
                Test("weather vane requires turntable links wind then stops when wind gone",()=>{using(var m=PartyFieldTests.Make("weather-vane")){var e=Deploy(m,"weather-vane");var table=m.Effects.First(x=>x.id==e.targetId);PartyFieldTests.Tick(m,.1f);Check(table.machine.angle==0,"spontaneous wind");var fan=Auxiliary(m,"fan-volume",e.position-Vector3.forward*1.5f);PartyFieldTests.Tick(m,.3f);Check(table.machine.angle>10&&e.force>.1f,"fan failed link angle="+table.machine.angle+" force="+e.force);m.Effects.Remove(fan);float a=table.machine.angle;PartyFieldTests.Tick(m,.2f);Check(Mathf.Abs(table.machine.angle-a)<.01f,"wind gone still drives");m.Effects.Remove(table);PartyFieldTests.Tick(m,.02f);Check(!m.Effects.Contains(e),"orphan vane");}});
                Test("missing turntable frost prerequisites show feedback no cooldown",()=>{foreach(var id in new[]{"weather-vane","frost-lock"})using(var m=PartyFieldTests.Make(id)){PartyFieldTests.Input(m,"p0","use_item");PartyFieldTests.Tick(m,.34f);Check(!m.Effects.Any(x=>x.owner=="p0")&&m.View("p0").players.First(x=>x.id=="p0").mechanicCooldown<1&&m.Events.Any(x=>x.text.Contains(id=="weather-vane"?"转台":"湿区")),"missing dependency charged silently "+id);}});
                Test("tempo public elevator E rejects offbeat then accepts beat no player lock",()=>{using(var m=PartyFieldTests.Make("heartbeat-tempo")){var e=PartyFieldTests.Deploy(m);var lift=Auxiliary(m,"floor-elevator",e.position+Vector3.right*2.35f);var b=m.Players["p1"];PartyControlTests.Place(m,b,PartyMachineryTests.Button(lift)+Vector3.up*.85f);m.Time=e.createdAt+.6f;PartyFieldTests.Input(m,"p1","interact");Check(!lift.machine.used,"offbeat accepted");PartyFieldTests.Tick(m,.1f,"p1",0,1);Check(b.position.z>e.position.z+.2f,"tempo locked movement");PartyControlTests.Place(m,b,PartyMachineryTests.Button(lift)+Vector3.up*.85f);m.Time=e.createdAt+1.41f;PartyFieldTests.Input(m,"p1","interact");Check(lift.machine.used,"green beat did not accept E");}});
                Test("frost snapshots existing wet only stronger inertia and jump counter",()=>{using(var m=PartyFieldTests.Make("frost-lock")){var e=Deploy(m,"frost-lock");Check(e.path.Length==2,"wrong snapshot");var b=m.Players["p1"];b.bodyProtectedUntil=m.Time+5;PartyControlTests.Place(m,b,new Vector3(0,1,0));PartyFieldTests.Tick(m,.16f,"p1",1,0);float x=b.position.x;PartyFieldTests.Tick(m,.2f);Check(b.position.x>x+.04f&&b.fieldStatus.Contains("凝结"),"no ice inertia");PartyFieldTests.Input(m,"p1","jump");PartyFieldTests.Tick(m,.06f);Check(b.airborne&&b.fieldStatus=="","ice blocked jump");}});
                Test("sponge removes two captured ice points without deleting life",()=>{using(var m=PartyFieldTests.Make("frost-lock")){var ice=Deploy(m,"frost-lock");m.Effects.RemoveAll(x=>x.mechanicId=="wet-trail");var sponge=Auxiliary(m,"sponge-dry",ice.position);PartyFieldTests.Tick(m,.04f);Check(!m.Effects.Contains(ice)&&sponge.chainIndex==2&&sponge.stage=="saturated"&&m.Remaining("p0")==4,"sponge failed ice cap");}});
                Test("one portal endpoint dismantles both without any life consumption",()=>{using(var m=PartyFieldTests.Make("shot-portal")){var first=PortalPair(m);var attacker=m.Players["p1"];PartyControlTests.Place(m,attacker,first.position+Vector3.up*.85f+Vector3.back*1.4f);first.health=1;m.Item(attacker.equipped).asset.templateId="Melee";PartyFieldTests.Input(m,"p1","use_item");PartyFieldTests.Tick(m,.4f);Check(!m.Effects.Any(x=>x.mechanicId=="shot-portal")&&m.Remaining("p0")==4,"portal teardown leaked pair/life");}});
                Test("all virtual source consume and finish conserve remaining identities",()=>{foreach(var d in PartyMechanicRegistry.All.Where(x=>x.family=="virtual"))using(var m=PartyFieldTests.Make(d.id)){var e=Deploy(m,d.id);m.Item(e.sourceInstance).state=ItemState.Consumed;PartyFieldTests.Tick(m,.02f);Check(!m.Effects.Contains(e)&&m.Remaining("p0")==3&&m.Remaining("p1")==4,"source leak "+d.id);m.Finish("timeout");Check(!m.Effects.Any(x=>x.kind=="PartyMechanic"),"finish leak "+d.id);}});
            }
            finally{Cache.SetValue(null,old);}if(failures.Count>0)throw new Exception(string.Join("\n",failures));Debug.Log("PARTY_VIRTUAL_PASSED "+passed+" authority scenarios / ten virtual interactions");
        }
    }
}
